import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.C7GIOALF.js";const m=JSON.parse('{"title":"Kingdoms","description":"","frontmatter":{},"headers":[],"relativePath":"formats/bang-like/variants/kingdoms.md","filePath":"formats/bang-like/variants/kingdoms.md","lastUpdated":null}'),s={name:"formats/bang-like/variants/kingdoms.md"};function o(i,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="kingdoms" tabindex="-1">Kingdoms <a class="header-anchor" href="#kingdoms" aria-label="Permalink to &quot;Kingdoms&quot;">​</a></h1><p><a href="./../">BANG-like versions</a> · <strong>Rules: TheChurchIsHere&#39;s 5–6-player variant</strong></p><h2 id="players-and-materials" tabindex="-1">Players and materials <a class="header-anchor" href="#players-and-materials" aria-label="Permalink to &quot;Players and materials&quot;">​</a></h2><p>Each player brings a Commander deck. Use basic lands as role cards, separate from the decks:</p><table tabindex="0"><thead><tr><th>Players</th><th style="text-align:right;">Plains: King</th><th style="text-align:right;">Forest: Knight</th><th style="text-align:right;">Mountains: Bandits</th><th style="text-align:right;">Swamp: Assassin</th><th style="text-align:right;">Island: Usurper</th></tr></thead><tbody><tr><td>5</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td><td style="text-align:right;">0</td></tr><tr><td>6</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr></tbody></table><p>Use matching card backs or opaque sleeves so the roles cannot be identified before they are dealt.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Shuffle the listed role cards and deal one face down to each player.</li><li>Each player secretly looks at their card.</li><li>The King reveals their role and starts at <strong>50 life</strong>. Everyone else starts at the normal Commander total of <strong>40</strong>.</li><li>Prepare Commander libraries and command zones, draw seven cards, and take normal multiplayer mulligans.</li><li>The King takes the first turn.</li></ol><p>Play normal individual Commander turns. Commander tax and the normal 21-combat-damage threshold remain in effect; the King does not receive an increased commander-damage threshold.</p><h2 id="roles-and-victory-conditions" tabindex="-1">Roles and victory conditions <a class="header-anchor" href="#roles-and-victory-conditions" aria-label="Permalink to &quot;Roles and victory conditions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Full objective</th></tr></thead><tbody><tr><td>King</td><td>Be the last survivor, or finish as the last two players with the Knight.</td></tr><tr><td>Knight</td><td>Protect the current King. If the King and Knight are the last two players, both win.</td></tr><tr><td>Bandit</td><td>Eliminate the King. The Bandits win when the King dies, regardless of which Bandits remain. The Usurper&#39;s role exchange is the special exception below.</td></tr><tr><td>Assassin</td><td>Eliminate everyone else and be the last survivor.</td></tr><tr><td>Usurper</td><td>Personally deliver the killing blow to the King, take the throne, and continue pursuing the King&#39;s objective. Taking the throne does not itself end the game.</td></tr></tbody></table><p>The King and Knight&#39;s allegiance does not create shared turns, shared life, or permission to block for one another. Ordinary free-for-all rules still govern the actual cards.</p><h2 id="role-secrecy" tabindex="-1">Role secrecy <a class="header-anchor" href="#role-secrecy" aria-label="Permalink to &quot;Role secrecy&quot;">​</a></h2><p>Except for the King and a Usurper taking the throne, players may not reveal their role card until the game ends. They may claim a role, truthfully or falsely, but may not show the card as proof.</p><p>Unlike BANG! Magic, this source does not tell an eliminated player to reveal their card immediately.</p><h2 id="usurping-the-throne" tabindex="-1">Usurping the throne <a class="header-anchor" href="#usurping-the-throne" aria-label="Permalink to &quot;Usurping the throne&quot;">​</a></h2><p>If the Usurper delivers the killing blow to the King:</p><ol><li>The Usurper reveals their role.</li><li>Exchange the King and Usurper roles.</li><li>The new King goes to <strong>50 life</strong>.</li><li>The former King remains in the game as the new Usurper at <strong>1 life</strong>.</li><li>The Knight&#39;s objective becomes protecting the new King.</li><li>Continue the game instead of awarding the Bandits a victory for that exchange.</li></ol><p>This rule changes roles and life totals. It does not say to restart the game or exchange decks, hands, or permanents.</p><h3 id="commander-damage-and-poison-option" tabindex="-1">Commander-damage and poison option <a class="header-anchor" href="#commander-damage-and-poison-option" aria-label="Permalink to &quot;Commander-damage and poison option&quot;">​</a></h3><p>In a later reply, the original poster says their group resets commander damage or poison when one of those conditions lets the Usurper defeat the King. They explicitly describe this as varying by table. Decide whether to use that reset before play; without a rule addressing the lethal counters or damage, changing a life total alone does not cure that loss condition.</p><h2 id="cases-the-source-leaves-open" tabindex="-1">Cases the source leaves open <a class="header-anchor" href="#cases-the-source-leaves-open" aria-label="Permalink to &quot;Cases the source leaves open&quot;">​</a></h2><p>The post does not fully define “killing blow” for simultaneous eliminations, concessions, shared effects, or non-damage loss conditions. It also does not establish a general priority rule for alternate-win cards. Record those choices before a game that can produce them.</p><p>The other roles suggested in the comments, such as the Fool, are separate house-rule proposals. They are not extra roles in the five- and six-player distributions above.</p><p>Source: <a href="https://www.reddit.com/r/EDH/comments/1plyyj/kingdoms_edh_variant/" target="_blank" rel="noreferrer">TheChurchIsHere&#39;s Kingdoms post and replies</a>. <a href="./../sources/kingdoms-edh-reddit.html">Archived notes</a>.</p>',25)])])}const p=t(s,[["render",o]]);export{m as __pageData,p as default};
